          const rawWindAccZ = clamp(accZ - thrustAccZ + cd * 0.5 * (v.z + prevObs.vel.z), -9.5, 9.5);

          windFastX += 0.32 * (rawWindAccX - windFastX);
          windFastZ += 0.32 * (rawWindAccZ - windFastZ);
          windMedX += 0.10 * (rawWindAccX - windMedX);
          windMedZ += 0.10 * (rawWindAccZ - windMedZ);
        }
      }

      const estMass = clamp(15.0 / thrustScale, 0.6, 0.95);
      const cd = 0.42 / estMass;

      // Transient gust derivative (decays in ~0.09s so no lingering bias after gust ends)
      const gustTransX = windFastX - windMedX;
      const gustTransZ = windFastZ - windMedZ;

      // 2. Navigation state machine
      let tx = p.x, ty = p.y, tz = p.z;
      let vxDes = 0, vyDes = 0, vzDes = 0;
      let kpX = 4.5, kdX = 3.6;
      let kpZ = 6.5, kdZ = 4.2;
      let kpY = 6.5, kdY = 4.0;
      let pinPad = false;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
          gateIntZ = 0;
          gateIntY = 0;
        }

