import("./tasks/drone-hard/task.mjs").then(async ({ TASK, GATES, PAD, random, trialParameters }) => {
  const { initialState } = await import("./tasks/drone-hard/sim.mjs");
  const makeController = (await import("/workspace/controller.js")).default;
  const seed = 103, params = trialParameters(seed), state = initialState(params), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const ctrl = makeController();
  const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
  const vec = (v, n) => Object.fromEntries(Object.entries(v).map(([k, val]) => [k, val + noise(n)]));
  for (let step = 0; step < 600 && !state.reason; step++) {
    const obs = {
      t: +state.t.toFixed(4), pos: vec(state.pos, TASK.positionNoise), vel: vec(state.vel, TASK.velocityNoise),
      att: vec(state.att, TASK.attitudeNoise), rates: vec(state.rates, TASK.rateNoise),
      gateIndex: state.gateIndex, nextGate: state.gateIndex < 3 ? GATES[state.gateIndex] : null, pad: PAD
    };
    const act = ctrl.step(obs);
    if (state.t >= 5.15 && state.t <= 5.68 && step % 5 === 0) {
      console.log(state.t.toFixed(2), "pos:", state.pos.x.toFixed(3), state.pos.y.toFixed(3), state.pos.z.toFixed(3), "vel:", state.vel.x.toFixed(2), state.vel.z.toFixed(2), "act:", act.roll.toFixed(3), act.pitch.toFixed(3));
    }
    // integrate
    for (let sub = 0; sub < 2; sub++) {
      const dt = 0.005, old = { ...state.pos }, { att, rates } = state, inertia = TASK.inertia * params.mass / TASK.baseMass;
      const torque = {};
      for (const axis of ["roll", "pitch"]) {
        const err = act[axis] - att[axis];
        state.integral[axis] = Math.max(-0.35, Math.min(0.35, state.integral[axis] + err * dt));
        torque[axis] = inertia * (65 * err - 13 * rates[axis] + 22 * state.integral[axis]);
      }
      torque.yaw = inertia * 8 * (act.yawRate - rates.yaw);
      const MX = [-1, 1, 1, -1], MZ = [-1, -1, 1, 1], SP = [1, -1, 1, -1];
      for (let i = 0; i < 4; i++) {
        const des = act.thrust * 4 + torque.roll * MZ[i] / (4 * TASK.arm) - torque.pitch * MX[i] / (4 * TASK.arm) + torque.yaw * SP[i] / (4 * TASK.yawCoefficient);
        const tgt = Math.max(0, Math.min(4, des)) * (i === params.weakMotor ? 1 - params.weakness : 1);
        state.motors[i] += (tgt - state.motors[i]) * (1 - Math.exp(-dt / params.lag));
      }
      const sum = state.motors.reduce((a, b) => a + b, 0);
      const mom = (s) => state.motors.reduce((a, f, i) => a + f * s[i], 0);
      rates.roll += (TASK.arm * mom(MZ) / inertia - 0.4 * rates.roll) * dt;
      rates.pitch += (-TASK.arm * mom(MX) / inertia - 0.4 * rates.pitch) * dt;
      rates.yaw += (TASK.yawCoefficient * mom(SP) / inertia - 0.4 * rates.yaw) * dt;
      for (const axis of ["roll", "pitch", "yaw"]) att[axis] += rates[axis] * dt;
      const bx = Math.sin(att.pitch) * Math.cos(att.roll), bz = -Math.sin(att.roll);
      const dir = { x: Math.cos(att.yaw) * bx + Math.sin(att.yaw) * bz, y: Math.cos(att.pitch) * Math.cos(att.roll), z: -Math.sin(att.yaw) * bx + Math.cos(att.yaw) * bz };
      const wind = { ...params.baseWind };
      for (const g of params.gusts) if (state.t >= g.start && state.t < g.start + g.duration) { wind.x += g.x; wind.y += g.y; wind.z += g.z; }
      for (const axis of ["x", "y", "z"]) {
        const force = sum * dir[axis] + TASK.linearDrag * (wind[axis] - state.vel[axis]);
        state.vel[axis] += (force / params.mass - (axis === "y" ? 9.81 : 0)) * dt;
        state.pos[axis] += state.vel[axis] * dt;
      }
      state.t += dt;
    }
  }
});
