      const nearWall = Math.abs(p.x) > 2.35 || Math.abs(p.z) > 2.35;
      const maxAcc = nearWall ? 6.5 : 5.5;
      const Ax = clamp(axPD + cd * velFiltX - windCleanX - gustBrakeX, -maxAcc, maxAcc);
      const Az = clamp(azPD + cd * velFiltZ - windCleanZ - gustBrakeZ, -maxAcc, maxAcc);
      const Ay = pinPad ? 6.0 : clamp(9.81 + ayPD + cd * velFiltY, 2.5, 16.5);

      // 4. Nonlinear mapping to desired roll, pitch, and thrust
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const AbodyX = cy * Ax - sy * Az;
      const AbodyZ = sy * Ax + cy * Az;

      let maxTilt = nearWall ? 0.55 : 0.48;
      if (obs.gateIndex === 3 && p.y < 0.18) {
        maxTilt = pinPad ? 0.155 : 0.24;
      }
      const desPitch = clamp(Math.atan2(AbodyX, Ay), -maxTilt, maxTilt);
      const desRoll = clamp(-Math.atan2(AbodyZ, Math.hypot(AbodyX, Ay)), -maxTilt, maxTilt);

      const dirY = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const thrust = clamp(Ay / (thrustScale * dirY), 0.05, 0.95);

