      const gustBrakeZ = 0.30 * gustDeltaZ;

      const axPD = kpX * ex + kdX * (vxDes - velFiltX);
      const azPD = kpZ * ez + kdZ * (vzDes - velFiltZ);
      const ayPD = kpY * ey + kdY * (vyDes - velFiltY);

      const nearWall = Math.abs(p.x) > 2.35 || Math.abs(p.z) > 2.35;
      const maxAcc = nearWall ? 6.5 : 5.5;
