      const gustBrakeZ = 0.38 * gustDeltaZ;

      const axPD = Math.min(maxAxPD, kpX * ex + kdX * (vxDes - velFiltX));
      const azPD = kpZ * ez + kdZ * (vzDes - velFiltZ);
      const ayPD = kpY * ey + kdY * (vyDes - velFiltY);

