      const Az = clamp(azPD + cd * velFiltZ - windCleanZ - gustBrakeZ, -7.2, 7.2);
      const Ay = pinPad ? 6.0 : clamp(9.81 + ayPD + cd * velFiltY, 2.5, 16.5);

